// Input Validation
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

if (!requestData.candidates || !Array.isArray(requestData.candidates)) {
  throw new Error('candidates array is required');
}

if (requestData.candidates.length === 0) {
  throw new Error('candidates array cannot be empty');
}

// Validate structure
const validCandidates = requestData.candidates.filter(c => 
  c.first_name && c.last_name && (c.email || c.phone)
);

if (validCandidates.length === 0) {
  throw new Error('No valid candidates found. Each candidate must have first_name, last_name, and either email or phone.');
}

return [{
  json: {
    candidates: validCandidates,
    total_input: requestData.candidates.length,
    valid_count: validCandidates.length,
    timestamp: new Date().toISOString()
  }
}];

// Normalize fields: clean phone, email, names
const candidates = $input.first().json.candidates;

function normalizePhone(phone) {
  if (!phone) return null;
  return phone.replace(/[^0-9]/g, '').slice(-10); // Last 10 digits
}

function normalizeEmail(email) {
  if (!email) return null;
  return email.toLowerCase().trim();
}

function normalizeName(name) {
  if (!name) return '';
  return name.trim().toLowerCase().replace(/[^a-z]/g, '');
}

const normalized = candidates.map(c => ({
  json: {
    first_name: c.first_name.trim(),
    last_name: c.last_name.trim(),
    first_name_normalized: normalizeName(c.first_name),
    last_name_normalized: normalizeName(c.last_name),
    email: normalizeEmail(c.email),
    phone: normalizePhone(c.phone),
    company: (c.company || '').trim(),
    job_title: (c.job_title || '').trim(),
    linkedin_url: (c.linkedin_url || '').trim(),
    skills: Array.isArray(c.skills) ? c.skills : (c.skills || '').split(',').map(s => s.trim()),
    source: c.source || 'unknown'
  }
}));

return normalized;

// Fuzzy Matching - Levenshtein + exact email/phone match
const newCandidate = $input.first().json;
const masterDb = $('Load Master Database').all().map(item => item.json);

// Levenshtein distance function
function levenshtein(a, b) {
  const matrix = [];
  for (let i = 0; i <= b.length; i++) {
    matrix[i] = [i];
  }
  for (let j = 0; j <= a.length; j++) {
    matrix[0][j] = j;
  }
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

// Check for duplicates
let isDuplicate = false;
let matchedRecord = null;
let matchReason = '';

for (const existing of masterDb) {
  // Exact email match
  if (newCandidate.email && existing.email && newCandidate.email === existing.email) {
    isDuplicate = true;
    matchedRecord = existing;
    matchReason = 'exact_email_match';
    break;
  }

  // Exact phone match + name similarity ≤2
  if (newCandidate.phone && existing.phone && newCandidate.phone === existing.phone) {
    const nameDist = levenshtein(
      newCandidate.first_name_normalized + newCandidate.last_name_normalized,
      (existing.first_name_normalized || '') + (existing.last_name_normalized || '')
    );
    if (nameDist <= 2) {
      isDuplicate = true;
      matchedRecord = existing;
      matchReason = 'phone_match_name_similar';
      break;
    }
  }

  // Name Levenshtein ≤2 + same company (flag for review)
  const fullNameDist = levenshtein(
    newCandidate.first_name_normalized + newCandidate.last_name_normalized,
    (existing.first_name_normalized || '') + (existing.last_name_normalized || '')
  );
  if (fullNameDist <= 2 && newCandidate.company && existing.company && 
      newCandidate.company.toLowerCase() === existing.company.toLowerCase()) {
    isDuplicate = true;
    matchedRecord = existing;
    matchReason = 'fuzzy_name_same_company';
    break;
  }
}

return [{
  json: {
    ...newCandidate,
    is_duplicate: isDuplicate,
    matched_record: matchedRecord,
    match_reason: matchReason
  }
}];

// Merge duplicate records - prefer newest data
const newData = $input.first().json;
const existing = newData.matched_record;

const merged = {
  // Use new data if exists, otherwise keep existing
  first_name: newData.first_name || existing.first_name,
  last_name: newData.last_name || existing.last_name,
  email: newData.email || existing.email,
  phone: newData.phone || existing.phone,
  company: newData.company || existing.company,
  job_title: newData.job_title || existing.job_title,
  linkedin_url: newData.linkedin_url || existing.linkedin_url,
  skills: [...new Set([...(existing.skills || []), ...(newData.skills || [])])],
  sources: [...new Set([...(existing.sources || []), newData.source])],
  last_updated: new Date().toISOString(),
  match_reason: newData.match_reason,
  duplicate_count: (existing.duplicate_count || 0) + 1
};

return [{
  json: {
    ...merged,
    action: 'update_existing',
    record_id: existing.id
  }
}];

