// Calculate Candidate Score (0-100)
const item = $input.first().json;

let score = 0;

// Completeness scoring
if (item.email) score += 10;
if (item.phone) score += 10;
if (item.linkedin_url) score += 10;
if (item.company) score += 5;
if (item.job_title) score += 5;
if (item.skills && item.skills.length >= 5) score += 10;

// Experience scoring (estimate from skills count and title)
const skillsCount = item.skills?.length || 0;
if (skillsCount >= 15) score += 20;      // 10+ years
else if (skillsCount >= 10) score += 15; // 6-10 years
else if (skillsCount >= 5) score += 10;  // 3-5 years
else score += 5;                          // 0-2 years

// Engagement scoring
if (item.result === 'valid') score += 10; // Recent/valid email
if (item.source === 'application') score += 10; // Active application

// Email verification bonus
if (item.result === 'valid') score += 5;

// Assign tier
let tier = 'C';
if (score >= 80) tier = 'A';
else if (score >= 60) tier = 'B';

return [{
  json: {
    first_name: item.first_name,
    last_name: item.last_name,
    email: item.email,
    email_valid: item.result === 'valid',
    phone: item.phone,
    company: item.company,
    company_size: item.employees || 'Unknown',
    job_title: item.choices?.[0]?.message?.content || item.job_title,
    linkedin_url: item.linkedin_url,
    skills: JSON.parse(item.choices?.[0]?.message?.content || JSON.stringify(item.skills || [])),
    candidate_score: score,
    tier: tier,
    source: item.source,
    created_at: new Date().toISOString()
  }
}];

// Assign recruiter (round-robin or specialization)
const candidate = $input.first().json;

const recruiters = [
  { name: 'Alice Johnson', specialization: 'Tech', email: 'alice@ibovi.com' },
  { name: 'Bob Smith', specialization: 'Healthcare', email: 'bob@ibovi.com' },
  { name: 'Carol Lee', specialization: 'Finance', email: 'carol@ibovi.com' }
];

// Simple round-robin based on candidate hash
const hash = (candidate.email || '').split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
const assignedRecruiter = recruiters[hash % recruiters.length];

return [{
  json: {
    ...candidate,
    assigned_recruiter: assignedRecruiter.name,
    assigned_recruiter_email: assignedRecruiter.email
  }
}];

